export function localizeMessage(value){
 for(const [prefix,de,en] of [['Fehlende Zeichen: ','Diese Schrift enthält nicht: ','This font is missing: '],['Konturen prüfen: ','Konturen prüfen: ','Check contours: ']])if(value.startsWith(prefix))return (language==='en'?en:de)+value.slice(prefix.length);
 return engineMessages.get(value)?.[language==='en'?1:0]??(language==='de'?value:t('generationFailed'));
}
